function Sun({ children }) {
  return jsxs('p', {
    className: 'ecv-note',
    children: [jsx('span', { className: 'ecv-sun', children: '☉' }), children],
  })
}

function clock(secs) {
  const m = Math.floor(secs / 60)
  const s = Math.floor(secs % 60)
  return m + ':' + String(s).padStart(2, '0')
}

const WAVE = Array.from({ length: 100 }, (_, i) => 5 + ((i * 17 + 11) % 14))

function RadioPlayer({ track, duration, playing, onToggle, elapsed, onSeek }) {
  const filled = duration ? elapsed / duration : 0
  return jsxs('div', {
    className: 'ecv-player',
    children: [
      jsx('button', {
        type: 'button',
        className: 'ecv-play',
        'aria-label': playing ? 'Pause' : 'Play',
        onClick: onToggle,
        children: playing ? '❚❚' : '▶',
      }),
      jsxs('div', {
        className: 'ecv-player-main',
        children: [
          jsxs('div', {
            className: 'ecv-player-row',
            children: [
              jsx('div', { className: 'ecv-player-title', children: '♪  ' + track }),
              jsx('div', { className: 'ecv-times', children: clock(elapsed) + ' / ' + clock(duration) }),
            ],
          }),
          jsx('div', {
            className: 'ecv-wave',
            role: 'slider',
            'aria-label': 'Seek',
            'aria-valuemin': 0,
            'aria-valuemax': duration,
            'aria-valuenow': elapsed,
            onClick: (e) => {
              const box = e.currentTarget.getBoundingClientRect()
              onSeek(Math.round(((e.clientX - box.left) / box.width) * duration))
            },
            children: WAVE.map((h, i) =>
              jsx('i', {
                'data-on': i / WAVE.length < filled ? '1' : undefined,
                style: { height: 8 + h + 'px' },
              }, i),
            ),
          }),
        ],
      }),
    ],
  })
}

